module digit_distance_sum(input clk, input rst_n, input start, input [31:0] A, input [31:0] B, output reg [31:0] result, output reg done); localparam MAX_ITER = 10000; localparam MODULUS = 1000000007; localparam INT10_0 = 1; localparam INT10_1 = 10; localparam INT10_2 = 100; localparam INT10_3 = 1000; localparam INT10_4 = 10000; localparam INT10_5 = 100000; localparam INT10_6 = 1000000; localparam INT10_7 = 10000000; reg [19:0] digit_counts[7:0][10:0]; reg [31:0] current_num; reg [15:0] count_iter; reg [2:0] state; localparam IDLE = 3'd0, CALCULATE_COUNTS = 3'd1, CALCULATE_DISTANCE = 3'd2, COMPLETE = 3'd3; always @(posedge clk) begin if (!rst_n) begin state <= IDLE; result <= 0; done <= 0; current_num <= 0; count_iter <= 0; for (int i=0; i<8; i++) begin for (int j=0; j<10; j++) begin digit_counts[i][j] <= 0; end end end else begin case (state) IDLE: begin if (start) begin if (A <= B) begin state <= CALCULATE_COUNTS; current_num <= A; count_iter <= 0; end else begin result <= 0; done <= 1; state <= COMPLETE; end end end CALCULATE_COUNTS: begin if (count_iter < MAX_ITER && current_num <= B) begin digit_counts[0][(current_num / INT10_0) % 10] <= digit_counts[0][(current_num / INT10_0) % 10] + 1; digit_counts[1][(current_num / INT10_1) % 10] <= digit_counts[1][(current_num / INT10_1) % 10] + 1; digit_counts[2][(current_num / INT10_2) % 10] <= digit_counts[2][(current_num / INT10_2) % 10] + 1; digit_counts[3][(current_num / INT10_3) % 10] <= digit_counts[3][(current_num / INT10_3) % 10] + 1; digit_counts[4][(current_num / INT10_4) % 10] <= digit_counts[4][(current_num / INT10_4) % 10] + 1; digit_counts[5][(current_num / INT10_5) % 10] <= digit_counts[5][(current_num / INT10_5) % 10] + 1; digit_counts[6][(current_num / INT10_6) % 10] <= digit_counts[6][(current_num / INT10_6) % 10] + 1; digit_counts[7][(current_num / INT10_7) % 10] <= digit_counts[7][(current_num / INT10_7) % 10] + 1; current_num <= current_num + 1; count_iter <= count_iter + 1; state <= CALCULATE_COUNTS; end else begin state <= CALCULATE_DISTANCE; end end CALCULATE_DISTANCE: begin state <= COMPLETE; end COMPLETE: begin done <= 1; result <= total_sum % MODULUS; state <= COMPLETE; endcase end end endmodule